import secrets
import hashlib


class AccountService:
    def __init__(self) -> None:
        # map: normalized email -> account dict
        self._accounts = {}
        # map: token -> normalized email
        self._reset_tokens = {}
        # set of used tokens (to distinguish used vs unknown)
        self._used_tokens = set()

    @staticmethod
    def _normalize_email(email: str) -> str:
        return email.strip().lower()

    @staticmethod
    def _hash_password(password: str, salt: bytes) -> str:
        return hashlib.pbkdf2_hmac(
            "sha256", password.encode("utf-8"), salt, 100_000
        ).hex()

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        norm = self._normalize_email(email)
        if norm in self._accounts:
            raise ValueError("An account with this email already exists.")
        salt = secrets.token_bytes(16)
        self._accounts[norm] = {
            "salt": salt,
            "password_hash": self._hash_password(password, salt),
            "is_admin": bool(is_admin),
        }

    def login(self, email: str, password: str) -> bool:
        norm = self._normalize_email(email)
        account = self._accounts.get(norm)
        if account is None:
            return False
        candidate = self._hash_password(password, account["salt"])
        return secrets.compare_digest(candidate, account["password_hash"])

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester = self._accounts.get(self._normalize_email(requester_email))
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets.")
        target = self._normalize_email(target_email)
        if target not in self._accounts:
            raise ValueError("Target account does not exist.")
        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")
        if token in self._used_tokens:
            raise ValueError("Reset token has already been used.")
        target = self._reset_tokens.pop(token, None)
        if target is None:
            raise ValueError("Invalid reset token.")
        self._used_tokens.add(token)
        account = self._accounts[target]
        salt = secrets.token_bytes(16)
        account["salt"] = salt
        account["password_hash"] = self._hash_password(new_password, salt)
